using namespace std;

using ll = long long;

const ll N = 1e6 + 5, M = 25;

int n, m, k, r, x[N], idx[N], p[N], ans, res;
vector<int> vec[N];
struct node
{
	int mx, mn;

	const friend node operator+(const node &x, const node &y) { return {max(x.mx, y.mx), min(x.mn, y.mn)}; }

} st[M][N];

int calc(int l, int r)
{
	int k = __lg(r - l + 1);
	node res = st[k][l] + st[k][r - (1 << k) + 1];
	return res.mx - res.mn;
}

void del()
{}

void init() {}

void solve()
{
	cin >> n >> k >> r;
	for (int i = 1; i <= n; ++i)
		cin >> st[0][i].mx, st[0][i].mn = st[0][i].mx;
	for (int j = 1; j <= __lg(n); ++j)
	{
		for (int i = 1; i + (1 << j) - 1 <= n; ++i)
