#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 1e5 + 5;

int n, g, q;
ll m, a[N], b[N], c[N], ans;
bool tp;

namespace brute_force
{
	int k, fl2 = -1;

	void solve1(int l, int r)
	{
		k = r - l + 1;
		for (int i = l; i <= r; ++i)
			b[i - l + 1] = a[i];
		sort(b + 1, b + k + 1);
		for (int i = 1; i <= k; ++i)
			(c[i] = b[i % k + 1] - b[i]) < 0 ? c[i] += m : 0;
		sort(c + 1, c + k + 1);
		for (int i = 1; i <= min(k, g); ++i)
			ans ^= c[i];
		cout << ans << endl;
	}

	bool check2()
	{
		for (int i = 1; i <= n; ++i)
		{
			if (a[i] != i)
				return 0;
		}
		return 1;
	}

	void solve2()
	{
		for (int l, r; q--;)
		{
			cin >> l >> r;
			if (tp)
			{
				l = ((l ^ ans) + n - 1) % n + 1;
				r = ((r ^ ans) + n - 1) % n + 1;
				if (l > r)
					swap(l, r);
			}
			ans = 0;
			k = r - l + 1;
			// cerr << k << ' ' << g << endl;
			if (k <= g)
			{
				ans ^= l - r + m;
